/**
 * Public TypeScript types for the web app.
 *
 * Two layers:
 *   - `db.generated.ts` mirrors raw table shapes (regenerated by
 *     `nflgrades gen-types`). Never edit by hand.
 *   - This file curates names, narrows union types, and adds view-shaped
 *     types (joins, aggregates) used by API routes and components.
 *
 * See docs/adr/0005-hand-written-ts-types-with-codegen-guardrail.md
 */

import type {
  TeamsRow,
  PlayersRow,
  SeasonGradesRow,
  CareerGradesRow,
  DepthChartsRow,
} from "./db.generated";

export type Conference = "AFC" | "NFC";
export type Division = "North" | "South" | "East" | "West";
export type DataTier = 1 | 2 | 3;

export type Team = Omit<TeamsRow, "conference" | "division"> & {
  conference: Conference;
  division: Division;
};

export type Player = Pick<
  PlayersRow,
  "player_id" | "gsis_id" | "full_name" | "position" | "current_team_id"
>;

export type SeasonGrade = Omit<SeasonGradesRow, "data_tier"> & {
  data_tier: DataTier;
};

export type CareerGrade = CareerGradesRow;

export type DepthChartEntry = DepthChartsRow;

// ---------------------------------------------------------------------------
// View-shaped types (joins of multiple tables used by the UI).
// Defined here (not in db.generated.ts) because they don't correspond to any
// single table — they're the shape returned by `lib/queries.ts` functions.
// ---------------------------------------------------------------------------

/**
 * One row in the QB leaderboard: a season grade joined with player name,
 * primary team, and the three raw QB-v1 components.
 *
 * `n_dropbacks` is the sample_size on the `qb_epa_per_dropback` component,
 * which the QB feature extraction uses as the post-filter dropback count.
 */
export type LeaderboardEntry = {
  player_id: number;
  full_name: string;
  position: string;
  season: number;
  composite_grade: number;
  composite_z: number;
  percentile: number;
  qualified: boolean;
  confidence: number | null;
  data_tier: number;
  team_abbr: string | null;
  n_dropbacks: number | null;
  epa_per_dropback: number | null;
  cpoe: number | null;
  success_rate: number | null;
};

/** One stat_components row rehydrated for a player detail page. */
export type StatComponentDetail = {
  component_name: string;
  raw_value: number | null;
  adjusted_value: number | null;
  z_score: number | null;
  sample_size: number | null;
  /** false when stored for audit but omitted from headline composite (TE earn, ADR-0016). */
  used_in_composite?: boolean;
};

/** One season grade plus its component breakdown, for the player page. */
export type SeasonGradeDetail = {
  season: number;
  position: string;
  composite_grade: number;
  composite_z: number;
  percentile: number;
  qualified: boolean;
  confidence: number | null;
  data_tier: number;
  team_abbr: string | null;
  components: StatComponentDetail[];
};

/** Minimal player metadata — enough to render a header. */
export type PlayerMeta = {
  player_id: number;
  gsis_id: string | null;
  full_name: string;
  position: string;
  current_team_abbr: string | null;
};

/** What /players/[id] renders. */
export type PlayerDetail = {
  player: PlayerMeta;
  grades: SeasonGradeDetail[];
};
